use super::*;
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}

#[test]
fn original_dictionary_native_ranges_keep_original_input_and_exact_paged_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let hex=law["payloadHex"].as_str().unwrap();let source:Vec<u8>=hex.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let policy=&law["grant"];let axis=|key:&str|policy[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:axis("items"),maximum_copy_bytes:axis("copy"),maximum_capacity_bytes:axis("capacity"),maximum_release_bytes:axis("release"),maximum_depth:axis("depth")};
 for cancellation in [0,1,2,3,5,32]{
  let(mut dictionary,born,released)=observe(||RetainedSourceDictionary::new(&source));assert_eq!((born,released),(0,0));let changed=source.clone();let(result,born,released)=observe(||dictionary.begin_record(&changed,0,changed.len(),grant));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(dictionary.receipt().is_none());
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,born,released)=observe(||dictionary.begin_record(&source,0,source.len(),denied).unwrap());assert_eq!(step,RetainedSourceDictionaryStep::Blocked);assert_eq!((born,released),(0,0));}
  let(_,born,released)=observe(||dictionary.begin_record(&source,0,source.len(),grant).unwrap());assert_eq!((born,released),(0,0));assert_eq!(dictionary.take_receipt().unwrap(),(grant,RetainedCloneProgress{copied_items:1,..Default::default()}));let(mut total_birth,mut total_release)=(0,0);
  for _ in 0..cancellation{
   if dictionary.is_ready(){break}let(demand,born,released)=observe(||dictionary.demands(&source).unwrap());assert_eq!((born,released),(0,0));for(axis,denied)in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==1&&demand.depth==0)||(axis==2&&demand.capacity_bytes==0){continue}let(step,born,released)=observe(||dictionary.advance(&source,denied).unwrap());assert_eq!(step,RetainedSourceDictionaryStep::Blocked);assert_eq!((born,released),(0,0));}
   let(_,born,released)=observe(||dictionary.advance(&source,grant).unwrap());let(received,progress)=dictionary.receipt().unwrap();assert_eq!(received,grant);assert!(progress.fits(grant));assert_eq!(progress.copied_bytes,0);assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));total_birth+=born;total_release+=released;let(step,born,released)=observe(||dictionary.advance(&source,grant).unwrap());assert_eq!(step,RetainedSourceDictionaryStep::Blocked);assert_eq!((born,released),(0,0));dictionary.take_receipt().unwrap();
  }
  if cancellation==32{assert!(dictionary.is_ready());assert_eq!(dictionary.len(),law["values"].as_array().unwrap().len());for(index,value)in law["values"].as_array().unwrap().iter().enumerate(){let(text,born,released)=observe(||{let(start,end)=dictionary.resolve_range(&source,index).unwrap();&source[start..end]});assert_eq!((born,released),(0,0));assert_eq!(text,value.as_str().unwrap().as_bytes());assert!((source.as_ptr()as usize..=source.as_ptr()as usize+source.len()).contains(&(text.as_ptr()as usize)));}}
  dictionary.cancel();for _ in 0..128{if dictionary.terminal_is_empty(){break}let demand=dictionary.demands(&source).unwrap();for(axis,denied)in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}].into_iter().enumerate(){if(axis==1&&demand.depth==0)||(axis==2&&demand.release_bytes==0){continue}let(step,born,released)=observe(||dictionary.close_step(&source,denied).unwrap());assert_eq!(step,RetainedSourceDictionaryStep::Blocked);assert_eq!((born,released),(0,0));}let(_,born,released)=observe(||dictionary.close_step(&source,grant).unwrap());let(received,progress)=dictionary.take_receipt().unwrap();assert_eq!(received,grant);assert_eq!(progress.copied_bytes,0);assert!(progress.fits(grant));assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));total_birth+=born;total_release+=released;}
  assert!(dictionary.terminal_is_empty());assert_eq!(total_birth,total_release);let(_,born,released)=observe(||drop(dictionary));assert_eq!((born,released),(0,0));
 }
 eprintln!("[DEBUG] original dictionary native ranges retain exact original pointer and extent; zero payload copy, paid paged births/releases and partial cancellation receipts conserve native backing");
}
